      "step": [
        {
          "@type": "HowToStep",
          "position": 1,
          "name": "Request Free Quote",
          "text": "Contact STS at (844) 699-2913 or submit our online quote request with your equipment types, estimated quantities, and preferred pickup timing.",
          "url": "https://www.stselectronicrecyclinginc.com/CONTACT-STS-PAGE"
        },
        {
          "@type": "HowToStep",
          "position": 2,
          "name": "Schedule Pickup",
          "text": "Our dispatch team coordinates a convenient pickup window for your Bakersfield facility, accommodating business hours and security protocols.",
          "image": "https://www.stselectronicrecyclinginc.com/images/2017/compressed/mac-2585220_1920.jpg"
        },
        {
          "@type": "HowToStep",
          "position": 3,
          "name": "Secure Transport",
          "text": "Equipment collected in Bakersfield is staged securely and transported to an STS certified processing facility with strict chain-of-custody tracking.",
          "image": "https://www.stselectronicrecyclinginc.com/images/2017/compressed/mac-2585220_1920.jpg"
        },
        {
          "@type": "HowToStep",
          "position": 4,
          "name": "Asset Tracking & Data Destruction",
          "text": "Hardware is audited by serial number and processed with NIST SP 800-88 Rev. 2 compliant data sanitization or physical destruction.",
          "image": "https://www.stselectronicrecyclinginc.com/images/2017/compressed/mac-2585220_1920.jpg"
        },
        {
          "@type": "HowToStep",
          "position": 5,
          "name": "Environmental Processing",
          "text": "Components undergo responsible material separation with zero-landfill disposal, while qualifying functional assets are evaluated for remarketing.",
          "image": "https://www.stselectronicrecyclinginc.com/images/2017/compressed/mac-2585220_1920.jpg"
        },
        {
          "@type": "HowToStep",
          "position": 6,
          "name": "Certificate of Destruction",
          "text": "Receive an itemized inventory summary and official serialized Certificate of Destruction satisfying HIPAA, GLBA, and corporate audit requirements.",
          "url": "https://www.stselectronicrecyclinginc.com/certificate-of-destruction-services"
        }
      ]
